            event.preventDefault();
            dis.dispatch({ action: Action.ViewUser, member });
        };
        return { avatar, text, onClick, resourceId, type: resolvedType };
    }
    if (resolvedType === PillType.RoomMention && resourceId && (resourceId[0] === "!" || resourceId[0] === "#")) {
        const client = MatrixClientPeg.get();
        const resolvedRoom = resourceId[0] === "#"
            ? client.getRooms().find((candidate) => candidate.getCanonicalAlias() === resourceId || candidate.getAltAliases().includes(resourceId))
            : client.getRoom(resourceId);
        if (!resolvedRoom) return { avatar: null, text: null, onClick: null, resourceId, type: null };
        const space = resolvedRoom.isSpaceRoom();
        const avatar = shouldShowPillAvatar ? <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" /> : null;
        return { avatar, text: resolvedRoom.name || resourceId, onClick: null, resourceId, type: space ? "space" : resolvedType };
    }
    return { avatar: null, text: null, onClick: null, resourceId, type: null };
}
